      "invoice_settings?: { custom_fields?: { name: string; value: string; }[] | ''; default_payment_method?: string; footer?: string; rendering_options?: { amount_tax_display?: '' | 'exclude_tax' | 'include_inclusive_tax'; template?: string; } | ''; };",
      "metadata?: object | '';",
